async function audit(ctx,action,entity,detail=''){
  await pool.query(`INSERT INTO audit_logs(tenant_id,outlet_id,user_id,username,action,entity,detail) VALUES($1,$2,$3,$4,$5,$6,$7)`,[ctx?.tenantId||null,ctx?.outletId||null,ctx?.user?.id||null,ctx?.user?.username||'system',action,entity,String(detail||'')]);
}

async function auth(req,res,next){
  try{
    const token=(req.headers.authorization||'').replace(/^Bearer\s+/i,'');
    const p=jwt.verify(token,JWT_SECRET);
    const user=(await pool.query(`SELECT id,name,username,email,active,is_platform_admin,created_at FROM users WHERE id=$1 AND active=true`,[p.sub])).rows[0];
    if(!user) throw new Error('user');
    const membership=(await pool.query(`SELECT tu.tenant_id,tu.default_outlet_id,tu.active,r.name role,r.permissions,t.name tenant_name,t.status tenant_status
      FROM tenant_users tu JOIN tenants t ON t.id=tu.tenant_id LEFT JOIN roles r ON r.id=tu.role_id
      WHERE tu.user_id=$1 AND tu.tenant_id=$2 AND tu.active=true`,[user.id,p.tenantId])).rows[0];
    if(!membership) throw new Error('tenant');
    const outletId=p.outletId||membership.default_outlet_id;
    const outlet=(await pool.query(`SELECT id,name,code,active FROM outlets WHERE id=$1 AND tenant_id=$2 AND active=true`,[outletId,membership.tenant_id])).rows[0];
    if(!outlet) throw new Error('outlet');
    const sub=(await pool.query(`SELECT s.status,s.expires_at,s.grace_until,sp.code plan_code,sp.name plan_name,sp.max_outlets,sp.max_users
      FROM subscriptions s JOIN subscription_plans sp ON sp.id=s.plan_id WHERE s.tenant_id=$1 ORDER BY s.created_at DESC LIMIT 1`,[membership.tenant_id])).rows[0]||null;
    req.ctx={user,tenantId:membership.tenant_id,tenantName:membership.tenant_name,outletId:outlet.id,outletName:outlet.name,role:membership.role||'User',permissions:membership.permissions||[],subscription:sub};
    next();
  }catch{return res.status(401).json({error:'Sesi tidak valid. Silakan login kembali.'})}
}
function platformAdmin(req,res,next){if(!req.ctx.user.is_platform_admin)return res.status(403).json({error:'Akses platform admin diperlukan.'});next()}
function platformAuth(req,res,next){try{const token=(req.headers.authorization||'').replace(/^Bearer\s+/i,'');const p=jwt.verify(token,JWT_SECRET);if(!p.platform)throw new Error('platform');req.platform={userId:p.sub};next()}catch{return res.status(401).json({error:'Sesi admin tidak valid.'})}}
async function accurateRequest(url,{method='GET',token,sessionId,body}={}){const headers={Authorization:`Bearer ${token}`};if(sessionId)headers['X-Session-ID']=sessionId;let payload;if(body){headers['Content-Type']='application/x-www-form-urlencoded;charset=UTF-8';payload=new URLSearchParams();for(const [k,v] of Object.entries(body))if(v!==undefined&&v!==null)payload.append(k,String(v))}const r=await fetch(url,{method,headers,body:payload,redirect:'follow'});const text=await r.text();let d;try{d=JSON.parse(text)}catch{d={s:false,d:[text||`HTTP ${r.status}`]}}if(!r.ok||d.s===false)throw new Error(Array.isArray(d.d)?d.d.join('; '):(d.message||`Accurate HTTP ${r.status}`));return d}
async function accurateRefreshIfNeeded(tenantId,row){if(!row?.access_token)return row;if(row.token_expires_at&&new Date(row.token_expires_at)>new Date(Date.now()+24*3600*1000))return row;if(!row.refresh_token)throw new Error('Sesi Accurate Online sudah berakhir. Silakan hubungkan ulang.');const basic=Buffer.from(`${ACCURATE_CLIENT_ID}:${ACCURATE_CLIENT_SECRET}`).toString('base64');const body=new URLSearchParams({grant_type:'refresh_token',refresh_token:row.refresh_token});const r=await fetch(ACCURATE_TOKEN_URL,{method:'POST',headers:{Authorization:`Basic ${basic}`,'Content-Type':'application/x-www-form-urlencoded'},body});const d=await r.json();if(!r.ok||!d.access_token)throw new Error('Gagal memperbarui sesi Accurate Online.');const exp=new Date(Date.now()+Number(d.expires_in||1295999)*1000);await pool.query(`UPDATE integrations SET access_token=$2,refresh_token=COALESCE($3,refresh_token),token_expires_at=$4,updated_at=now() WHERE tenant_id=$1 AND provider='accurate_online'`,[tenantId,d.access_token,d.refresh_token||null,exp]);return {...row,access_token:d.access_token,refresh_token:d.refresh_token||row.refresh_token,token_expires_at:exp}}

function activeSubscription(req,res,next){const s=req.ctx.subscription;if(!s)return res.status(402).json({error:'Langganan belum aktif.'});const deadline=new Date(s.grace_until||s.expires_at);if(['cancelled','suspended'].includes(s.status)||deadline<new Date())return res.status(402).json({error:'Langganan ACIS POS telah berakhir. Silakan perpanjang untuk melanjutkan transaksi.'});next()}
