app.post('/api/login',async(req,res)=>{
  const {username,password,tenantId,outletId}=req.body||{};
  const u=(await pool.query(`SELECT * FROM users WHERE username=$1 AND active=true`,[String(username||'')])).rows[0];
  if(!u||!await bcrypt.compare(String(password||''),u.password_hash))return res.status(401).json({error:'Username atau password salah.'});
  const memberships=(await pool.query(`SELECT tu.tenant_id,tu.default_outlet_id,t.name tenant_name,r.name role,o.name outlet_name
    FROM tenant_users tu JOIN tenants t ON t.id=tu.tenant_id LEFT JOIN roles r ON r.id=tu.role_id LEFT JOIN outlets o ON o.id=tu.default_outlet_id
    WHERE tu.user_id=$1 AND tu.active=true AND t.status='active' ORDER BY t.name`,[u.id])).rows;
  if(!memberships.length)return res.status(403).json({error:'User belum terhubung ke bisnis aktif.'});
  const m=memberships.find(x=>x.tenant_id===tenantId)||memberships[0];
  const selectedOutlet=outletId||m.default_outlet_id;
  const token=jwt.sign({sub:u.id,tenantId:m.tenant_id,outletId:selectedOutlet},JWT_SECRET,{expiresIn:'12h'});
  res.json({token,user:{id:u.id,name:u.name,username:u.username,role:m.role,tenant:{id:m.tenant_id,name:m.tenant_name},outlet:{id:selectedOutlet,name:m.outlet_name}},memberships});
});


