app.post('/api/onboarding/register',async(req,res)=>{
  const b=req.body||{}; if(!b.businessName||!b.name||!b.username||!b.password)return res.status(400).json({error:'Nama bisnis, nama owner, username dan password wajib diisi.'});
  try{
    const out=await tx(async c=>{
      if((await c.query(`SELECT 1 FROM users WHERE username=$1`,[b.username])).rowCount)throw Object.assign(new Error('Username sudah digunakan.'),{status:409});
      const tenant=(await c.query(`INSERT INTO tenants(code,name) VALUES($1,$2) RETURNING *`,[String(b.businessCode||code('BIZ')).toUpperCase(),b.businessName])).rows[0];
      const outlet=(await c.query(`INSERT INTO outlets(tenant_id,code,name,address) VALUES($1,'MAIN',$2,$3) RETURNING *`,[tenant.id,b.outletName||'Toko Utama',b.address||''])).rows[0];
      const hash=await bcrypt.hash(String(b.password),10);
      const user=(await c.query(`INSERT INTO users(name,username,email,password_hash) VALUES($1,$2,$3,$4) RETURNING id,name,username,email`,[b.name,b.username,b.email||null,hash])).rows[0];
      const roles={}; for(const [name,permissions] of [['Administrator',['*']],['Kasir',['pos','sales.view','products.view']],['Manager',['dashboard','pos','products','inventory','purchases','sales','partners','reports']]])roles[name]=(await c.query(`INSERT INTO roles(tenant_id,name,permissions) VALUES($1,$2,$3::jsonb) RETURNING id`,[tenant.id,name,JSON.stringify(permissions)])).rows[0].id;
      await c.query(`INSERT INTO tenant_users(tenant_id,user_id,role_id,default_outlet_id) VALUES($1,$2,$3,$4)`,[tenant.id,user.id,roles.Administrator,outlet.id]);
      await c.query(`INSERT INTO tenant_settings(tenant_id,company_name,address,email) VALUES($1,$2,$3,$4)`,[tenant.id,b.businessName,b.address||'',b.email||'']);
      const plan=(await c.query(`SELECT id FROM subscription_plans WHERE code=$1`,[b.planCode||'MONTHLY'])).rows[0]||(await c.query(`SELECT id FROM subscription_plans WHERE active=true ORDER BY price_monthly LIMIT 1`)).rows[0];
      await c.query(`INSERT INTO subscriptions(tenant_id,plan_id,status,expires_at) VALUES($1,$2,'trial',now()+($3::int * interval '1 day'))`,[tenant.id,plan.id,String(TRIAL_DAYS)]);
      for(const x of ['Makanan','Minuman','Lainnya'])await c.query(`INSERT INTO categories(tenant_id,name) VALUES($1,$2)`,[tenant.id,x]);
      for(const x of ['Pcs','Box','Botol'])await c.query(`INSERT INTO units(tenant_id,name) VALUES($1,$2)`,[tenant.id,x]);
      await c.query(`INSERT INTO partners(tenant_id,code,type,name) VALUES($1,'CUST-001','customer','Pelanggan Umum'),($1,'SUP-001','supplier','Supplier Utama')`,[tenant.id]);
      return {tenant,outlet,user};
    });
    res.status(201).json({ok:true,trialDays:TRIAL_DAYS,...out});
  }catch(e){res.status(e.status||400).json({error:e.message||'Onboarding gagal.'})}
});

