app.get('/api/shifts/current',auth,async(req,res)=>{const r=(await pool.query(`SELECT cs.*,COALESCE((SELECT COUNT(*) FROM sales s WHERE s.shift_id=cs.id),0)::int transactions,COALESCE((SELECT SUM(total) FROM sales s WHERE s.shift_id=cs.id),0)::numeric sales_total,COALESCE((SELECT SUM(LEAST(paid,total)) FROM sales s WHERE s.shift_id=cs.id AND lower(payment_method)='cash'),0)::numeric cash_sales FROM cashier_shifts cs WHERE cs.tenant_id=$1 AND cs.outlet_id=$2 AND cs.user_id=$3 AND cs.status='open' ORDER BY opened_at DESC LIMIT 1`,[req.ctx.tenantId,req.ctx.outletId,req.ctx.user.id])).rows[0];res.json({shift:r||null})});
app.get('/api/shifts',auth,async(req,res)=>{const rows=(await pool.query(`SELECT cs.*,u.name cashier,COALESCE(COUNT(s.id),0)::int transactions,COALESCE(SUM(s.total),0)::numeric sales_total,COALESCE(SUM(CASE WHEN lower(s.payment_method)='cash' THEN LEAST(s.paid,s.total) ELSE 0 END),0)::numeric cash_sales FROM cashier_shifts cs JOIN users u ON u.id=cs.user_id LEFT JOIN sales s ON s.shift_id=cs.id WHERE cs.tenant_id=$1 AND cs.outlet_id=$2 GROUP BY cs.id,u.name ORDER BY cs.opened_at DESC LIMIT 200`,[req.ctx.tenantId,req.ctx.outletId])).rows;res.json({items:rows})});
app.post('/api/shifts/open',auth,activeSubscription,async(req,res)=>{const exists=(await pool.query(`SELECT id FROM cashier_shifts WHERE tenant_id=$1 AND outlet_id=$2 AND user_id=$3 AND status='open'`,[req.ctx.tenantId,req.ctx.outletId,req.ctx.user.id])).rows[0];if(exists)return res.status(409).json({error:'Masih ada shift yang terbuka.'});const r=(await pool.query(`INSERT INTO cashier_shifts(tenant_id,outlet_id,user_id,opening_cash,notes) VALUES($1,$2,$3,$4,$5) RETURNING *`,[req.ctx.tenantId,req.ctx.outletId,req.ctx.user.id,n(req.body.openingCash),req.body.notes||''])).rows[0];await audit(req.ctx,'OPEN','shift',r.id);res.json(r)});
app.post('/api/shifts/:id/close',auth,activeSubscription,async(req,res)=>{const r=(await pool.query(`UPDATE cashier_shifts SET status='closed',closed_at=now(),closing_cash=$4,notes=CASE WHEN $5='' THEN notes ELSE $5 END WHERE id=$1 AND tenant_id=$2 AND outlet_id=$3 AND status='open' RETURNING *`,[req.params.id,req.ctx.tenantId,req.ctx.outletId,n(req.body.closingCash),req.body.notes||''])).rows[0];if(!r)return res.status(404).json({error:'Shift aktif tidak ditemukan.'});await audit(req.ctx,'CLOSE','shift',r.id);res.json(r)});

