app.get('/api/dashboard',auth,async(req,res)=>{const t=req.ctx.tenantId,o=req.ctx.outletId;const [stats,low,recent,daily,topMonth]=await Promise.all([
 pool.query(`SELECT COALESCE(SUM(total) FILTER(WHERE created_at::date=current_date),0) total_today,COUNT(*) FILTER(WHERE created_at::date=current_date) transactions_today,COALESCE(SUM(total) FILTER(WHERE date_trunc('month',created_at)=date_trunc('month',now())),0) total_month FROM sales WHERE tenant_id=$1 AND outlet_id=$2`,[t,o]),
 pool.query(`SELECT p.*,COALESCE(sb.quantity,0) stock FROM products p LEFT JOIN stock_balances sb ON sb.product_id=p.id AND sb.tenant_id=p.tenant_id AND sb.outlet_id=$2 WHERE p.tenant_id=$1 AND p.active=true AND COALESCE(sb.quantity,0)<=p.min_stock ORDER BY stock ASC LIMIT 50`,[t,o]),
 pool.query(`SELECT * FROM sales WHERE tenant_id=$1 AND outlet_id=$2 ORDER BY created_at DESC LIMIT 8`,[t,o]),
 pool.query(`SELECT d::date date,COALESCE(SUM(s.total),0) total FROM generate_series(current_date-6,current_date,'1 day') d LEFT JOIN sales s ON s.tenant_id=$1 AND s.outlet_id=$2 AND s.created_at::date=d::date GROUP BY d ORDER BY d`,[t,o]),
 pool.query(`SELECT si.name produk,SUM(si.qty)::numeric qty,SUM(si.subtotal)::numeric omzet FROM sale_items si JOIN sales s ON s.id=si.sale_id AND s.tenant_id=si.tenant_id WHERE s.tenant_id=$1 AND s.outlet_id=$2 AND date_trunc('month',s.created_at)=date_trunc('month',now()) GROUP BY si.name ORDER BY qty DESC,omzet DESC LIMIT 8`,[t,o])]);
 const productCount=n((await pool.query(`SELECT COUNT(*) c FROM products WHERE tenant_id=$1 AND active=true`,[t])).rows[0].c);const st=stats.rows[0];res.json({totalToday:n(st.total_today),transactionsToday:n(st.transactions_today),totalMonth:n(st.total_month),products:productCount,lowStock:low.rows.map(camelProduct),recent:recent.rows.map(camelSale),daily:daily.rows.map(x=>({date:x.date,total:n(x.total)})),topProductsMonth:topMonth.rows.map(x=>({name:x.produk,qty:n(x.qty),revenue:n(x.omzet)}))})});

app.get('/api/reports/summary',auth,async(req,res)=>{const from=String(req.query.from||'1900-01-01'),to=String(req.query.to||'2999-12-31'),t=req.ctx.tenantId,o=req.ctx.outletId;const sales=(await pool.query(`SELECT s.*,COALESCE(json_agg(json_build_object('productId',si.product_id,'name',si.name,'qty',si.qty,'subtotal',si.subtotal)) FILTER(WHERE si.id IS NOT NULL),'[]') items FROM sales s LEFT JOIN sale_items si ON si.sale_id=s.id AND si.tenant_id=s.tenant_id WHERE s.tenant_id=$1 AND s.outlet_id=$2 AND s.created_at::date BETWEEN $3::date AND $4::date GROUP BY s.id ORDER BY s.created_at DESC`,[t,o,from,to])).rows.map(camelSale);const expenses=(await pool.query(`SELECT amount FROM expenses WHERE tenant_id=$1 AND (outlet_id=$2 OR outlet_id IS NULL) AND created_at::date BETWEEN $3::date AND $4::date`,[t,o,from,to])).rows;const revenue=sales.reduce((a,b)=>a+b.total,0),cogs=sales.reduce((a,b)=>a+b.costTotal,0),expense=expenses.reduce((a,b)=>a+n(b.amount),0),byProduct={};for(const s of sales)for(const i of s.items){byProduct[i.productId]??={name:i.name,qty:0,revenue:0};byProduct[i.productId].qty+=n(i.qty);byProduct[i.productId].revenue+=n(i.subtotal)}res.json({revenue,cogs,grossProfit:revenue-cogs,expenses:expense,netProfit:revenue-cogs-expense,transactions:sales.length,topProducts:Object.values(byProduct).sort((a,b)=>b.qty-a.qty).slice(0,10),sales})});

async function buildReportData(ctx,type,from,to){
 const t=ctx.tenantId,o=ctx.outletId;let rows=[],title='Laporan',note='',statement=null;
 if(type==='sales_item'){title='Penjualan per Barang';rows=(await pool.query(`SELECT si.sku,si.name produk,SUM(si.qty)::numeric qty,SUM(si.subtotal)::numeric omzet FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.tenant_id=$1 AND s.outlet_id=$2 AND s.created_at::date BETWEEN $3::date AND $4::date GROUP BY si.sku,si.name ORDER BY omzet DESC`,[t,o,from,to])).rows}
 else if(type==='sales_payment'){title='Penjualan per Metode Bayar';rows=(await pool.query(`SELECT payment_method metode,COUNT(*)::int transaksi,SUM(total)::numeric nilai_penjualan FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date GROUP BY payment_method ORDER BY nilai_penjualan DESC`,[t,o,from,to])).rows}
 else if(type==='sales_shift'){title='Penjualan per Shift';rows=(await pool.query(`SELECT cs.id shift,cs.opened_at mulai,cs.closed_at selesai,u.name kasir,COUNT(s.id)::int transaksi,COALESCE(SUM(s.total),0)::numeric total,COALESCE(SUM(CASE WHEN lower(s.payment_method)='cash' THEN LEAST(s.paid,s.total) ELSE 0 END),0)::numeric tunai FROM cashier_shifts cs JOIN users u ON u.id=cs.user_id LEFT JOIN sales s ON s.shift_id=cs.id WHERE cs.tenant_id=$1 AND cs.outlet_id=$2 AND cs.opened_at::date BETWEEN $3::date AND $4::date GROUP BY cs.id,u.name ORDER BY cs.opened_at DESC`,[t,o,from,to])).rows}
 else if(type==='sales_customer'){title='Penjualan per Pelanggan';rows=(await pool.query(`SELECT COALESCE(p.name,'Pelanggan Umum') pelanggan,COUNT(*)::int transaksi,SUM(s.total)::numeric total FROM sales s LEFT JOIN partners p ON p.id=s.customer_id WHERE s.tenant_id=$1 AND s.outlet_id=$2 AND s.created_at::date BETWEEN $3::date AND $4::date GROUP BY COALESCE(p.name,'Pelanggan Umum') ORDER BY total DESC`,[t,o,from,to])).rows}
 else if(type==='purchase_item'){title='Pembelian per Barang';rows=(await pool.query(`SELECT pi.name produk,SUM(pi.qty)::numeric qty,SUM(pi.subtotal)::numeric total FROM purchase_items pi JOIN purchases p ON p.id=pi.purchase_id WHERE p.tenant_id=$1 AND p.outlet_id=$2 AND p.created_at::date BETWEEN $3::date AND $4::date GROUP BY pi.name ORDER BY total DESC`,[t,o,from,to])).rows}
 else if(type==='purchase_supplier'){title='Pembelian per Pemasok';rows=(await pool.query(`SELECT COALESCE(sp.name,'Tanpa Supplier') pemasok,COUNT(*)::int transaksi,SUM(p.total)::numeric total FROM purchases p LEFT JOIN partners sp ON sp.id=p.supplier_id WHERE p.tenant_id=$1 AND p.outlet_id=$2 AND p.created_at::date BETWEEN $3::date AND $4::date GROUP BY COALESCE(sp.name,'Tanpa Supplier') ORDER BY total DESC`,[t,o,from,to])).rows}
 else if(type==='ap'){title='Hutang Usaha';rows=(await pool.query(`SELECT p.number dokumen,COALESCE(sp.name,'Tanpa Supplier') pemasok,p.created_at::date tanggal,p.total::numeric saldo,p.status FROM purchases p LEFT JOIN partners sp ON sp.id=p.supplier_id WHERE p.tenant_id=$1 AND p.outlet_id=$2 AND p.created_at::date<=$4::date AND p.status NOT IN ('paid','cancelled') ORDER BY p.created_at DESC`,[t,o,from,to])).rows}
 else if(type==='ar'){title='Piutang Usaha';rows=(await pool.query(`SELECT s.invoice dokumen,COALESCE(c.name,'Pelanggan Umum') pelanggan,s.created_at::date tanggal,s.total::numeric total,s.paid::numeric dibayar,GREATEST(s.total-s.paid,0)::numeric saldo FROM sales s LEFT JOIN partners c ON c.id=s.customer_id WHERE s.tenant_id=$1 AND s.outlet_id=$2 AND s.created_at::date<=$4::date AND s.paid<s.total ORDER BY s.created_at DESC`,[t,o,from,to])).rows}
 else if(type==='receipts_payment'){title='Penerimaan Uang per Metode Bayar';rows=(await pool.query(`SELECT payment_method metode,COUNT(*)::int transaksi,SUM(LEAST(paid,total))::numeric penerimaan FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date GROUP BY payment_method ORDER BY penerimaan DESC`,[t,o,from,to])).rows}
 else if(type==='ledger'){title='Buku Besar';note='Disusun dari jurnal operasional ACIS POS dan dikelompokkan menurut akun.';rows=(await pool.query(`SELECT tanggal,kode,akun,referensi,keterangan,debit,kredit,SUM(debit-kredit) OVER(PARTITION BY kode ORDER BY tanggal,referensi ROWS UNBOUNDED PRECEDING)::numeric saldo FROM (SELECT created_at::date tanggal,'1101' kode,'Kas & Bank' akun,invoice referensi,'Penerimaan penjualan' keterangan,LEAST(paid,total)::numeric debit,0::numeric kredit FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date UNION ALL SELECT created_at::date,'1102','Piutang Usaha',invoice,'Penjualan kredit',GREATEST(total-paid,0),0 FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date UNION ALL SELECT created_at::date,'4101','Penjualan',invoice,'Pendapatan penjualan',0,total FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date UNION ALL SELECT created_at::date,'5101','Harga Pokok Penjualan',invoice,'HPP penjualan',cost_total,0 FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date UNION ALL SELECT created_at::date,'1103','Persediaan',invoice,'Pengurangan persediaan',0,cost_total FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date UNION ALL SELECT created_at::date,'1103','Persediaan',number,'Pembelian persediaan',total,0 FROM purchases WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date UNION ALL SELECT created_at::date,'2101','Hutang Usaha',number,'Pembelian barang',0,total FROM purchases WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date UNION ALL SELECT created_at::date,'6101','Beban Operasional',description,'Biaya operasional',amount,0 FROM expenses WHERE tenant_id=$1 AND (outlet_id=$2 OR outlet_id IS NULL) AND created_at::date BETWEEN $3::date AND $4::date UNION ALL SELECT created_at::date,'1101','Kas & Bank',description,'Pembayaran biaya',0,amount FROM expenses WHERE tenant_id=$1 AND (outlet_id=$2 OR outlet_id IS NULL) AND created_at::date BETWEEN $3::date AND $4::date) x ORDER BY kode,tanggal,referensi`,[t,o,from,to])).rows}
 else if(type==='profit_loss'){title='Laporan Laba Rugi';note='Penyajian bertingkat (multi-step) dengan klasifikasi pendapatan, HPP dan beban.';const r=(await pool.query(`SELECT COALESCE((SELECT SUM(total) FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date),0)::numeric pendapatan,COALESCE((SELECT SUM(cost_total) FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date BETWEEN $3::date AND $4::date),0)::numeric hpp,COALESCE((SELECT SUM(amount) FROM expenses WHERE tenant_id=$1 AND (outlet_id=$2 OR outlet_id IS NULL) AND created_at::date BETWEEN $3::date AND $4::date),0)::numeric biaya`,[t,o,from,to])).rows[0];const pend=n(r.pendapatan),hpp=n(r.hpp),biaya=n(r.biaya),gross=pend-hpp,net=gross-biaya;rows=[{section:'PENDAPATAN',account:'Pendapatan Penjualan',amount:pend},{section:'HARGA POKOK PENJUALAN',account:'Harga Pokok Penjualan',amount:hpp},{section:'LABA KOTOR',account:'Laba Kotor',amount:gross,total:true},{section:'BEBAN OPERASIONAL',account:'Beban Operasional',amount:biaya},{section:'LABA USAHA',account:'Laba Bersih Periode Berjalan',amount:net,total:true}];statement={kind:'profit_loss',totals:{revenue:pend,cogs:hpp,grossProfit:gross,operatingExpenses:biaya,netProfit:net}}}
 else if(type==='balance_sheet'){title='Laporan Posisi Keuangan (Neraca)';note='Penyajian aset, liabilitas dan ekuitas pada tanggal laporan.';const r=(await pool.query(`SELECT COALESCE((SELECT SUM(LEAST(paid,total)) FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date<=$3::date),0)::numeric kas_masuk,COALESCE((SELECT SUM(total) FROM purchases WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date<=$3::date),0)::numeric pembelian,COALESCE((SELECT SUM(amount) FROM expenses WHERE tenant_id=$1 AND (outlet_id=$2 OR outlet_id IS NULL) AND created_at::date<=$3::date),0)::numeric biaya,COALESCE((SELECT SUM(GREATEST(total-paid,0)) FROM sales WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date<=$3::date),0)::numeric piutang,COALESCE((SELECT SUM(sb.quantity*p.cost) FROM stock_balances sb JOIN products p ON p.id=sb.product_id WHERE sb.tenant_id=$1 AND sb.outlet_id=$2),0)::numeric persediaan,COALESCE((SELECT SUM(total) FROM purchases WHERE tenant_id=$1 AND outlet_id=$2 AND created_at::date<=$3::date AND status NOT IN ('paid','cancelled')),0)::numeric hutang`,[t,o,to])).rows[0];const kas=n(r.kas_masuk)-n(r.pembelian)-n(r.biaya),piutang=n(r.piutang),persediaan=n(r.persediaan),assets=kas+piutang+persediaan,liabilities=n(r.hutang),equity=assets-liabilities;rows=[{section:'ASET LANCAR',account:'Kas & Bank',amount:kas},{section:'ASET LANCAR',account:'Piutang Usaha',amount:piutang},{section:'ASET LANCAR',account:'Persediaan',amount:persediaan},{section:'TOTAL ASET',account:'Total Aset',amount:assets,total:true},{section:'LIABILITAS JANGKA PENDEK',account:'Hutang Usaha',amount:liabilities},{section:'TOTAL LIABILITAS',account:'Total Liabilitas',amount:liabilities,total:true},{section:'EKUITAS',account:'Modal & Saldo Laba',amount:equity},{section:'TOTAL EKUITAS',account:'Total Ekuitas',amount:equity,total:true},{section:'TOTAL LIABILITAS DAN EKUITAS',account:'Total Liabilitas dan Ekuitas',amount:liabilities+equity,total:true}];statement={kind:'balance_sheet',totals:{assets,liabilities,equity,balanced:Math.abs(assets-(liabilities+equity))<1}}}
 return {type,title,note,from,to,rows,statement};
}
app.get('/api/reports/detail',auth,async(req,res)=>{res.json(await buildReportData(req.ctx,String(req.query.type||'sales_item'),String(req.query.from||'1900-01-01'),String(req.query.to||'2999-12-31')))});
app.get('/api/reports/export',auth,async(req,res)=>{const type=String(req.query.type||'sales_item'),format=String(req.query.format||'xlsx').toLowerCase(),from=String(req.query.from||'1900-01-01'),to=String(req.query.to||'2999-12-31');const d=await buildReportData(req.ctx,type,from,to);const settings=(await pool.query(`SELECT company_name FROM tenant_settings WHERE tenant_id=$1`,[req.ctx.tenantId])).rows[0]||{company_name:req.ctx.tenantName};const filename=`${d.title.replace(/[^a-zA-Z0-9]+/g,'_')}_${from}_${to}`;
 if(format==='xlsx'){const wb=new ExcelJS.Workbook();wb.creator='ACIS POS';const ws=wb.addWorksheet(d.title.slice(0,31));ws.mergeCells('A1:F1');ws.getCell('A1').value=settings.company_name;ws.getCell('A1').font={bold:true,size:16};ws.mergeCells('A2:F2');ws.getCell('A2').value=d.title;ws.getCell('A2').font={bold:true,size:14};ws.mergeCells('A3:F3');ws.getCell('A3').value=`Periode ${from} s.d. ${to}`;const keys=[...new Set(d.rows.flatMap(r=>Object.keys(r)).filter(k=>!['total'].includes(k)))];ws.addRow([]);const hr=ws.addRow(keys.map(k=>k.replaceAll('_',' ').toUpperCase()));hr.font={bold:true};hr.eachCell(c=>{c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFEAF5EE'}}});for(const row of d.rows){const rr=ws.addRow(keys.map(k=>row[k]??''));if(row.total)rr.font={bold:true};rr.eachCell(c=>{if(typeof c.value==='number')c.numFmt='#,##0.00'})}ws.columns.forEach(c=>c.width=22);res.setHeader('Content-Type','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');res.setHeader('Content-Disposition',`attachment; filename="${filename}.xlsx"`);await wb.xlsx.write(res);return res.end()}
 if(format==='pdf'){res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`attachment; filename="${filename}.pdf"`);const doc=new PDFDocument({size:'A4',margin:42,bufferPages:true});doc.pipe(res);doc.fontSize(16).font('Helvetica-Bold').text(settings.company_name,{align:'center'});doc.moveDown(.2).fontSize(14).text(d.title,{align:'center'});doc.font('Helvetica').fontSize(9).text(`Periode ${from} s.d. ${to}`,{align:'center'});doc.moveDown();if(d.note)doc.fillColor('#555').fontSize(8).text(d.note).fillColor('#111').moveDown();const keys=[...new Set(d.rows.flatMap(r=>Object.keys(r)).filter(k=>!['total'].includes(k)))];for(const row of d.rows){if(doc.y>740)doc.addPage();if(row.section&&['PENDAPATAN','HARGA POKOK PENJUALAN','BEBAN OPERASIONAL','ASET LANCAR','LIABILITAS JANGKA PENDEK','EKUITAS'].includes(row.section)){doc.moveDown(.4).font('Helvetica-Bold').fontSize(9).text(row.section);doc.font('Helvetica')}const label=row.account||row.keterangan||row.produk||row.pelanggan||row.pemasok||row.akun||row.dokumen||row.metode||row.referensi||'';const amount=row.amount??row.nilai??row.nilai_penjualan??row.total??row.omzet??row.saldo??row.penerimaan;doc.font(row.total?'Helvetica-Bold':'Helvetica').fontSize(9).text(String(label),42,doc.y,{width:360,continued:true});doc.text(amount!==undefined?new Intl.NumberFormat('id-ID').format(Number(amount||0)):'',410,doc.y,{width:140,align:'right'});doc.font('Helvetica');if(!label){doc.fontSize(7).text(keys.map(k=>`${k}: ${row[k]??''}`).join(' | '))}}doc.end();return}
 res.status(400).json({error:'Format ekspor harus xlsx atau pdf.'})});

// Accurate Online OAuth + one-way export (credentials remain server-side)
app.get('/api/integrations/accurate',auth,async(req,res)=>{const r=(await pool.query(`SELECT status,last_sync_at,remote_database_id,remote_database_alias FROM integrations WHERE tenant_id=$1 AND provider='accurate_online'`,[req.ctx.tenantId])).rows[0];res.json({status:r?.status||'not_connected',connected:r?.status==='connected',databaseId:r?.remote_database_id||'',databaseAlias:r?.remote_database_alias||'',lastSyncAt:r?.last_sync_at||null,oauthReady:!!(ACCURATE_CLIENT_ID&&ACCURATE_CLIENT_SECRET&&ACCURATE_REDIRECT_URI)})});
app.get('/api/integrations/accurate/oauth/start',auth,async(req,res)=>{if(!ACCURATE_CLIENT_ID||!ACCURATE_REDIRECT_URI)return res.status(503).json({error:'Integrasi Accurate belum diaktifkan oleh ACIS.'});const state=jwt.sign({tenantId:req.ctx.tenantId,userId:req.ctx.user.id,nonce:crypto.randomBytes(10).toString('hex')},JWT_SECRET,{expiresIn:'10m'});const u=new URL(ACCURATE_AUTHORIZE_URL);u.searchParams.set('client_id',ACCURATE_CLIENT_ID);u.searchParams.set('response_type','code');u.searchParams.set('redirect_uri',ACCURATE_REDIRECT_URI);u.searchParams.set('scope',ACCURATE_SCOPE);u.searchParams.set('state',state);res.json({url:u.toString()})});
app.get('/api/integrations/accurate/oauth/callback',async(req,res)=>{try{const state=jwt.verify(String(req.query.state||''),JWT_SECRET);const codev=String(req.query.code||'');if(!codev)throw new Error('Authorization code tidak tersedia.');const basic=Buffer.from(`${ACCURATE_CLIENT_ID}:${ACCURATE_CLIENT_SECRET}`).toString('base64');const body=new URLSearchParams({code:codev,grant_type:'authorization_code',redirect_uri:ACCURATE_REDIRECT_URI});const r=await fetch(ACCURATE_TOKEN_URL,{method:'POST',headers:{Authorization:`Basic ${basic}`,'Content-Type':'application/x-www-form-urlencoded'},body});const d=await r.json();if(!r.ok||!d.access_token)throw new Error(d.error_description||'Gagal mendapatkan akses Accurate.');const exp=new Date(Date.now()+Number(d.expires_in||1295999)*1000);await pool.query(`INSERT INTO integrations(tenant_id,provider,status,config,access_token,refresh_token,token_expires_at) VALUES($1,'accurate_online','authorized','{}'::jsonb,$2,$3,$4) ON CONFLICT(tenant_id,provider) DO UPDATE SET status='authorized',access_token=$2,refresh_token=$3,token_expires_at=$4,updated_at=now()`,[state.tenantId,d.access_token,d.refresh_token||null,exp]);res.send(`<html><body style="font-family:system-ui;padding:40px"><h2>Accurate Online terhubung.</h2><p>Anda dapat menutup jendela ini dan kembali ke ACIS POS.</p><script>setTimeout(()=>window.close(),1200)</script></body></html>`)}catch(e){res.status(400).send(`<html><body><h3>Integrasi gagal</h3><p>${String(e.message).replace(/[<>]/g,'')}</p></body></html>`)}});
app.get('/api/integrations/accurate/databases',auth,async(req,res)=>{let row=(await pool.query(`SELECT * FROM integrations WHERE tenant_id=$1 AND provider='accurate_online'`,[req.ctx.tenantId])).rows[0];row=await accurateRefreshIfNeeded(req.ctx.tenantId,row);if(!row?.access_token)return res.status(409).json({error:'Hubungkan Accurate Online terlebih dahulu.'});const d=await accurateRequest(`${ACCURATE_ACCOUNT_URL}/api/db-list.do`,{token:row.access_token});res.json({items:d.d||[]})});
app.post('/api/integrations/accurate/select-database',auth,activeSubscription,async(req,res)=>{let row=(await pool.query(`SELECT * FROM integrations WHERE tenant_id=$1 AND provider='accurate_online'`,[req.ctx.tenantId])).rows[0];row=await accurateRefreshIfNeeded(req.ctx.tenantId,row);const dbId=String(req.body.databaseId||'');const alias=String(req.body.databaseAlias||'');if(!dbId)return res.status(400).json({error:'Pilih database Accurate.'});const d=await accurateRequest(`${ACCURATE_ACCOUNT_URL}/api/open-db.do?id=${encodeURIComponent(dbId)}`,{token:row.access_token});const info=d||{};const host=info.host||info.apiHost||'https://public.accurate.id';const session=info.session||info.sessionId||info['session-id'];if(!session)throw new Error('Session database Accurate tidak ditemukan pada response Open DB.');await pool.query(`UPDATE integrations SET status='connected',remote_database_id=$2,remote_database_alias=$3,remote_host=$4,remote_session_id=$5,updated_at=now() WHERE tenant_id=$1 AND provider='accurate_online'`,[req.ctx.tenantId,dbId,alias,host,session]);res.json({ok:true,status:'connected',databaseId:dbId,databaseAlias:alias})});
app.post('/api/integrations/accurate/disconnect',auth,async(req,res)=>{await pool.query(`UPDATE integrations SET status='not_connected',access_token=null,refresh_token=null,token_expires_at=null,remote_database_id=null,remote_database_alias=null,remote_host=null,remote_session_id=null,updated_at=now() WHERE tenant_id=$1 AND provider='accurate_online'`,[req.ctx.tenantId]);res.json({ok:true})});
app.get('/api/integrations/accurate/logs',auth,async(req,res)=>{const rows=(await pool.query(`SELECT entity,local_reference,remote_id,status,message,created_at FROM accurate_sync_logs WHERE tenant_id=$1 ORDER BY created_at DESC LIMIT 100`,[req.ctx.tenantId])).rows;res.json({items:rows})});
app.post('/api/integrations/accurate/sync-now',auth,activeSubscription,async(req,res)=>{let integ=(await pool.query(`SELECT * FROM integrations WHERE tenant_id=$1 AND provider='accurate_online'`,[req.ctx.tenantId])).rows[0];if(!integ||integ.status!=='connected')return res.status(409).json({error:'Hubungkan dan pilih database Accurate Online terlebih dahulu.'});integ=await accurateRefreshIfNeeded(req.ctx.tenantId,integ);const sales=(await pool.query(`SELECT s.*,COALESCE(c.code,'CUST-001') customer_code,COALESCE(json_agg(json_build_object('sku',si.sku,'name',si.name,'qty',si.qty,'price',si.price,'subtotal',si.subtotal)) FILTER(WHERE si.id IS NOT NULL),'[]') items FROM sales s LEFT JOIN partners c ON c.id=s.customer_id LEFT JOIN sale_items si ON si.sale_id=s.id WHERE s.tenant_id=$1 AND s.outlet_id=$2 AND s.accurate_synced_at IS NULL GROUP BY s.id,c.code ORDER BY s.created_at LIMIT 100`,[req.ctx.tenantId,req.ctx.outletId])).rows;let ok=0,failed=0;const errors=[];for(const sale of sales){try{const inv={number:sale.invoice,customerNo:sale.customer_code,transDate:new Date(sale.created_at).toLocaleDateString('en-GB')};(sale.items||[]).forEach((it,i)=>{inv[`detailItem[${i}].itemNo`]=it.sku;inv[`detailItem[${i}].quantity`]=n(it.qty);inv[`detailItem[${i}].unitPrice`]=n(it.price)});const ir=await accurateRequest(`${integ.remote_host}${ACCURATE_INVOICE_PATH}`,{method:'POST',token:integ.access_token,sessionId:integ.remote_session_id,body:inv});const remoteInvoice=String(ir?.r?.id||ir?.r?.number||sale.invoice);let remoteReceipt='';if(n(sale.paid)>0){const rec={customerNo:sale.customer_code,transDate:new Date(sale.created_at).toLocaleDateString('en-GB'),number:`PAY-${sale.invoice}`,'detailInvoice[0].invoiceNo':sale.invoice,'detailInvoice[0].paymentAmount':Math.min(n(sale.paid),n(sale.total))};const rr=await accurateRequest(`${integ.remote_host}${ACCURATE_RECEIPT_PATH}`,{method:'POST',token:integ.access_token,sessionId:integ.remote_session_id,body:rec});remoteReceipt=String(rr?.r?.id||rr?.r?.number||'')}await pool.query(`UPDATE sales SET accurate_invoice_id=$2,accurate_receipt_id=$3,accurate_synced_at=now() WHERE id=$1`,[sale.id,remoteInvoice,remoteReceipt]);await pool.query(`INSERT INTO accurate_sync_logs(tenant_id,outlet_id,sale_id,entity,local_reference,remote_id,status,message) VALUES($1,$2,$3,'sale',$4,$5,'success','Faktur dan penerimaan berhasil dikirim')`,[req.ctx.tenantId,req.ctx.outletId,sale.id,sale.invoice,remoteInvoice]);ok++;await new Promise(r=>setTimeout(r,140))}catch(e){failed++;errors.push(`${sale.invoice}: ${e.message}`);await pool.query(`INSERT INTO accurate_sync_logs(tenant_id,outlet_id,sale_id,entity,local_reference,status,message) VALUES($1,$2,$3,'sale',$4,'failed',$5)`,[req.ctx.tenantId,req.ctx.outletId,sale.id,sale.invoice,e.message]);await new Promise(r=>setTimeout(r,140))}}await pool.query(`UPDATE integrations SET last_sync_at=now(),updated_at=now() WHERE tenant_id=$1 AND provider='accurate_online'`,[req.ctx.tenantId]);await audit(req.ctx,'SYNC','accurate_online',`success=${ok}, failed=${failed}`);res.json({ok:true,sent:ok,failed,errors})});

app.get('/api/users',auth,async(req,res)=>{const rows=(await pool.query(`SELECT u.id,u.name,u.username,u.email,u.active,u.created_at,r.name role,tu.default_outlet_id FROM tenant_users tu JOIN users u ON u.id=tu.user_id LEFT JOIN roles r ON r.id=tu.role_id WHERE tu.tenant_id=$1 ORDER BY u.created_at`,[req.ctx.tenantId])).rows;res.json({items:rows.map(x=>({id:x.id,name:x.name,username:x.username,email:x.email||'',role:x.role,active:x.active,createdAt:x.created_at,defaultOutletId:x.default_outlet_id}))})});
app.post('/api/users',auth,activeSubscription,async(req,res)=>{const b=req.body||{};try{const out=await tx(async c=>{const plan=(await c.query(`SELECT sp.max_users FROM subscriptions s JOIN subscription_plans sp ON sp.id=s.plan_id WHERE s.tenant_id=$1 ORDER BY s.created_at DESC LIMIT 1`,[req.ctx.tenantId])).rows[0];const count=n((await c.query(`SELECT COUNT(*) c FROM tenant_users WHERE tenant_id=$1 AND active=true`,[req.ctx.tenantId])).rows[0].c);if(plan&&count>=plan.max_users)throw Object.assign(new Error(`Batas user paket saat ini adalah ${plan.max_users}.`),{status:409});if((await c.query(`SELECT 1 FROM users WHERE username=$1`,[b.username])).rowCount)throw Object.assign(new Error('Username sudah digunakan.'),{status:409});const hash=await bcrypt.hash(b.password||'123456',10);const u=(await c.query(`INSERT INTO users(name,username,email,password_hash) VALUES($1,$2,$3,$4) RETURNING *`,[b.name||b.username,b.username,b.email||null,hash])).rows[0];const role=(await c.query(`SELECT id,name FROM roles WHERE tenant_id=$1 AND name=$2`,[req.ctx.tenantId,b.role||'Kasir'])).rows[0]||(await c.query(`SELECT id,name FROM roles WHERE tenant_id=$1 ORDER BY name LIMIT 1`,[req.ctx.tenantId])).rows[0];await c.query(`INSERT INTO tenant_users(tenant_id,user_id,role_id,default_outlet_id) VALUES($1,$2,$3,$4)`,[req.ctx.tenantId,u.id,role.id,b.outletId||req.ctx.outletId]);return {...u,role:role.name}});await audit(req.ctx,'CREATE','user',out.username);res.json({id:out.id,name:out.name,username:out.username,role:out.role,active:out.active,createdAt:out.created_at})}catch(e){res.status(e.status||400).json({error:e.message})}});
app.put('/api/users/:id',auth,activeSubscription,async(req,res)=>{const b=req.body||{};const out=await tx(async c=>{const u=(await c.query(`SELECT u.* FROM users u JOIN tenant_users tu ON tu.user_id=u.id WHERE u.id=$1 AND tu.tenant_id=$2`,[req.params.id,req.ctx.tenantId])).rows[0];if(!u)return null;if(b.password)await c.query(`UPDATE users SET password_hash=$2 WHERE id=$1`,[u.id,await bcrypt.hash(b.password,10)]);await c.query(`UPDATE users SET name=$2,active=$3 WHERE id=$1`,[u.id,b.name??u.name,b.active??u.active]);if(b.role){const role=(await c.query(`SELECT id FROM roles WHERE tenant_id=$1 AND name=$2`,[req.ctx.tenantId,b.role])).rows[0];if(role)await c.query(`UPDATE tenant_users SET role_id=$3 WHERE tenant_id=$1 AND user_id=$2`,[req.ctx.tenantId,u.id,role.id])}return u});if(!out)return res.status(404).json({error:'User tidak ditemukan.'});await audit(req.ctx,'UPDATE','user',out.username);res.json({ok:true})});

app.get('/api/settings',auth,async(req,res)=>{const s=(await pool.query(`SELECT * FROM tenant_settings WHERE tenant_id=$1`,[req.ctx.tenantId])).rows[0];res.json({companyName:s.company_name,address:s.address,phone:s.phone,email:s.email,taxRate:n(s.tax_rate),receiptHeader:s.receipt_header||'',receiptFooter:s.receipt_footer,currency:s.currency,lowStockThreshold:n(s.low_stock_threshold),receiptPaperWidth:n(s.receipt_paper_width)||80,receiptShowLogo:s.receipt_show_logo!==false,tenantName:req.ctx.tenantName,outletName:req.ctx.outletName,subscription:req.ctx.subscription})});
app.put('/api/settings',auth,activeSubscription,async(req,res)=>{const b=req.body||{};const s=(await pool.query(`UPDATE tenant_settings SET company_name=COALESCE($2,company_name),address=COALESCE($3,address),phone=COALESCE($4,phone),email=COALESCE($5,email),tax_rate=COALESCE($6,tax_rate),receipt_footer=COALESCE($7,receipt_footer),low_stock_threshold=COALESCE($8,low_stock_threshold),receipt_header=COALESCE($9,receipt_header),receipt_paper_width=COALESCE($10,receipt_paper_width),receipt_show_logo=COALESCE($11,receipt_show_logo),updated_at=now() WHERE tenant_id=$1 RETURNING *`,[req.ctx.tenantId,b.companyName??null,b.address??null,b.phone??null,b.email??null,b.taxRate==null?null:n(b.taxRate),b.receiptFooter??null,b.lowStockThreshold==null?null:n(b.lowStockThreshold),b.receiptHeader??null,b.receiptPaperWidth==null?null:n(b.receiptPaperWidth),b.receiptShowLogo==null?null:!!b.receiptShowLogo])).rows[0];await pool.query(`UPDATE tenants SET name=$2,updated_at=now() WHERE id=$1`,[req.ctx.tenantId,s.company_name]);await audit(req.ctx,'UPDATE','settings','company');res.json({companyName:s.company_name,address:s.address,phone:s.phone,email:s.email,taxRate:n(s.tax_rate),receiptHeader:s.receipt_header,receiptFooter:s.receipt_footer,lowStockThreshold:n(s.low_stock_threshold),receiptPaperWidth:n(s.receipt_paper_width),receiptShowLogo:s.receipt_show_logo})});
app.get('/api/audit',auth,async(req,res)=>{const rows=(await pool.query(`SELECT at,username,action,entity,detail FROM audit_logs WHERE tenant_id=$1 ORDER BY at DESC LIMIT 300`,[req.ctx.tenantId])).rows;res.json({items:rows.map(x=>({at:x.at,user:x.username,action:x.action,entity:x.entity,detail:x.detail}))})});

app.get('/api/subscription',auth,async(req,res)=>{res.json(req.ctx.subscription||{})});
app.get('/api/platform/tenants',platformAuth,async(req,res)=>{const rows=(await pool.query(`SELECT t.id,t.code,t.name,t.status,t.created_at,sp.code plan_code,sp.name plan,s.status subscription_status,s.started_at,s.expires_at,s.grace_until,(SELECT COUNT(*) FROM tenant_users tu WHERE tu.tenant_id=t.id AND tu.active) users,(SELECT COUNT(*) FROM outlets o WHERE o.tenant_id=t.id AND o.active) outlets,(SELECT u.id FROM tenant_users tu JOIN users u ON u.id=tu.user_id LEFT JOIN roles r ON r.id=tu.role_id WHERE tu.tenant_id=t.id AND tu.active=true ORDER BY CASE WHEN r.name='Administrator' THEN 0 ELSE 1 END,tu.created_at LIMIT 1) admin_user_id,(SELECT u.username FROM tenant_users tu JOIN users u ON u.id=tu.user_id LEFT JOIN roles r ON r.id=tu.role_id WHERE tu.tenant_id=t.id AND tu.active=true ORDER BY CASE WHEN r.name='Administrator' THEN 0 ELSE 1 END,tu.created_at LIMIT 1) admin_username FROM tenants t LEFT JOIN LATERAL(SELECT * FROM subscriptions s2 WHERE s2.tenant_id=t.id ORDER BY created_at DESC LIMIT 1)s ON true LEFT JOIN subscription_plans sp ON sp.id=s.plan_id ORDER BY t.created_at DESC`)).rows;res.json({items:rows})});
app.get('/api/platform/summary',platformAuth,async(req,res)=>{const [tenants,active,users]=await Promise.all([pool.query(`SELECT COUNT(*) c FROM tenants`),pool.query(`SELECT COUNT(*) c FROM tenants WHERE status='active'`),pool.query(`SELECT COUNT(*) c FROM tenant_users WHERE active=true`)]);res.json({tenants:n(tenants.rows[0].c),activeTenants:n(active.rows[0].c),users:n(users.rows[0].c)})});
app.get('/api/platform/plans',platformAuth,async(req,res)=>res.json({items:(await pool.query(`SELECT code,name,price_monthly,max_users,max_outlets FROM subscription_plans WHERE active=true ORDER BY price_monthly`)).rows}));
app.get('/api/platform/tenants/:id/users',platformAuth,async(req,res)=>{const rows=(await pool.query(`SELECT u.id,u.name,u.username,u.email,tu.active,r.name role FROM tenant_users tu JOIN users u ON u.id=tu.user_id LEFT JOIN roles r ON r.id=tu.role_id WHERE tu.tenant_id=$1 ORDER BY tu.created_at`,[req.params.id])).rows;res.json({items:rows})});

app.put('/api/platform/tenants/:id/status',platformAuth,async(req,res)=>{const status=String(req.body.status||'active');if(!['active','suspended','closed'].includes(status))return res.status(400).json({error:'Status tidak valid.'});const r=await pool.query(`UPDATE tenants SET status=$2,updated_at=now() WHERE id=$1 RETURNING id,name,status`,[req.params.id,status]);if(!r.rowCount)return res.status(404).json({error:'Tenant tidak ditemukan.'});if(status==='suspended')await pool.query(`UPDATE subscriptions SET status='suspended' WHERE tenant_id=$1 AND id=(SELECT id FROM subscriptions WHERE tenant_id=$1 ORDER BY created_at DESC LIMIT 1)`,[req.params.id]);else if(status==='active')await pool.query(`UPDATE subscriptions SET status='active' WHERE tenant_id=$1 AND id=(SELECT id FROM subscriptions WHERE tenant_id=$1 ORDER BY created_at DESC LIMIT 1)`,[req.params.id]);res.json(r.rows[0])});
app.put('/api/platform/tenants/:id/subscription',platformAuth,async(req,res)=>{const b=req.body||{};const plan=(await pool.query(`SELECT id,code FROM subscription_plans WHERE code=$1 AND active=true`,[b.planCode])).rows[0];if(!plan)return res.status(400).json({error:'Paket tidak valid.'});const startDate=b.startedAt?new Date(b.startedAt):new Date();let endDate=b.expiresAt?new Date(b.expiresAt):null;if(!endDate){endDate=new Date(startDate);plan.code==='ANNUAL'?endDate.setFullYear(endDate.getFullYear()+1):endDate.setMonth(endDate.getMonth()+1)}const current=(await pool.query(`SELECT id FROM subscriptions WHERE tenant_id=$1 ORDER BY created_at DESC LIMIT 1`,[req.params.id])).rows[0];if(current)await pool.query(`UPDATE subscriptions SET plan_id=$2,status='active',started_at=$3,expires_at=$4,grace_until=null WHERE id=$1`,[current.id,plan.id,startDate,endDate]);else await pool.query(`INSERT INTO subscriptions(tenant_id,plan_id,status,started_at,expires_at) VALUES($1,$2,'active',$3,$4)`,[req.params.id,plan.id,startDate,endDate]);await pool.query(`UPDATE tenants SET status='active',updated_at=now() WHERE id=$1`,[req.params.id]);res.json({ok:true,planCode:plan.code,startedAt:startDate,expiresAt:endDate})});
app.put('/api/platform/tenants/:id/users/:userId/status',platformAuth,async(req,res)=>{const active=!!req.body.active;const r=await pool.query(`UPDATE tenant_users SET active=$3 WHERE tenant_id=$1 AND user_id=$2 RETURNING tenant_id,user_id,active`,[req.params.id,req.params.userId,active]);if(!r.rowCount)return res.status(404).json({error:'User tenant tidak ditemukan.'});res.json(r.rows[0])});
app.post('/api/platform/tenants/:id/reset-password',platformAuth,async(req,res)=>{const b=req.body||{};const userId=b.userId||(await pool.query(`SELECT tu.user_id FROM tenant_users tu LEFT JOIN roles r ON r.id=tu.role_id WHERE tu.tenant_id=$1 ORDER BY CASE WHEN r.name='Administrator' THEN 0 ELSE 1 END,tu.created_at LIMIT 1`,[req.params.id])).rows[0]?.user_id;if(!userId)return res.status(404).json({error:'User admin tenant tidak ditemukan.'});const temp=b.password||`Acis${Math.random().toString(36).slice(2,7)}!`;const hash=await bcrypt.hash(temp,10);await pool.query(`UPDATE users SET password_hash=$2 WHERE id=$1`,[userId,hash]);res.json({ok:true,temporaryPassword:temp})});


